"""Source-bound stopped-body occupancy; does not infer statutory exceptions."""
import hashlib
import json
import math
from pathlib import Path

RATE_HZ = 20
MIN_STOP_FRAMES = 40
EXCEPTIONS = ('entering_or_exiting_alley_or_driveway', 'disabled_vehicle',
              'avoiding_traffic_conflict', 'official_duties',
              'police_direction', 'emergency')


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def rectangle(value, name):
    if not isinstance(value, list) or len(value) != 4:
        raise ValueError('Missing ' + name)
    box = tuple(float(v) for v in value)
    if not all(math.isfinite(v) for v in box) or not (box[0] < box[2] and box[1] < box[3]):
        raise ValueError('Invalid ' + name)
    return box


def _clip(vertices, axis, limit, keep_greater):
    if not vertices:
        return []
    result = []
    before = vertices[-1]
    def inside(point):
        return point[axis] >= limit-1e-9 if keep_greater else point[axis] <= limit+1e-9
    for current in vertices:
        if inside(current) != inside(before):
            delta = current[axis]-before[axis]
            factor = (limit-before[axis])/delta
            result.append((before[0]+factor*(current[0]-before[0]),
                           before[1]+factor*(current[1]-before[1])))
        if inside(current):
            result.append(current)
        before = current
    return result


def overlap_area(body, box):
    if not isinstance(body, list) or len(body) != 4:
        raise ValueError('Missing original full body')
    points = []
    for vertex in body:
        if not isinstance(vertex, list) or len(vertex) != 2:
            raise ValueError('Invalid original body vertex')
        p = tuple(float(v) for v in vertex)
        if not all(math.isfinite(v) for v in p):
            raise ValueError('Nonfinite original body vertex')
        points.append(p)
    if len({(round(x, 8), round(y, 8)) for x, y in points}) != 4:
        raise ValueError('Degenerate original body')
    cross = [(points[(i+1)%4][0]-points[i][0]) *
             (points[(i+2)%4][1]-points[(i+1)%4][1]) -
             (points[(i+1)%4][1]-points[i][1]) *
             (points[(i+2)%4][0]-points[(i+1)%4][0]) for i in range(4)]
    if not (all(v > 1e-8 for v in cross) or all(v < -1e-8 for v in cross)):
        raise ValueError('Invalid original body winding')
    clipped = points
    for axis, limit, keep_greater in ((0, box[0], True), (0, box[2], False),
                                      (1, box[1], True), (1, box[3], False)):
        clipped = _clip(clipped, axis, limit, keep_greater)
    if len(clipped) < 3:
        return 0.0
    return abs(sum(a[0]*b[1]-b[0]*a[1]
                   for a, b in zip(clipped, clipped[1:]+clipped[:1])))/2


def measure(samples_path, geometry_path, exception_path):
    paths = [Path(samples_path), Path(geometry_path), Path(exception_path)]
    for path in paths:
        if not path.is_file():
            raise ValueError('Missing required source: ' + path.name)
    geometry = json.loads(paths[1].read_text())
    facility = rectangle(geometry.get('bicycle_facility_native_xy_bounds_m'), 'bicycle facility bounds')
    alley = rectangle(geometry.get('alley_entrance_native_xy_bounds_m'), 'alley entrance bounds')
    if type(geometry.get('road_id')) is not int or type(geometry.get('driving_lane_id')) is not int:
        raise ValueError('Missing Native road/lane identity')
    if type(geometry.get('bicycle_lane_id')) is not int:
        raise ValueError('Missing Native bicycle lane identity')
    context = json.loads(paths[2].read_text())
    if set(context.get('exceptions', {})) != set(EXCEPTIONS):
        raise ValueError('Incomplete statutory exception fields')
    if context.get('source_kind') != 'synthetic_scene_request':
        raise ValueError('Unrecognized exception source kind')
    if any(type(context['exceptions'][key]) is not bool for key in EXCEPTIONS):
        raise ValueError('Invalid statutory exception value')
    rows = [json.loads(s) for s in paths[0].read_text().splitlines() if s.strip()]
    if len(rows) < MIN_STOP_FRAMES:
        raise ValueError('Too few original Native samples')
    stopped = []
    areas = []
    frames = []
    times = []
    for row in rows:
        frame, time, speed = row.get('native_frame'), row.get('time_s'), row.get('speed_mps')
        if type(frame) is not int or frame < 0 or type(time) not in (int, float) or not math.isfinite(time):
            raise ValueError('Invalid original frame/time')
        if type(speed) not in (int, float) or not math.isfinite(speed) or speed < 0:
            raise ValueError('Invalid original speed')
        if frames and (frame <= frames[-1] or time <= times[-1] or abs(time-times[-1]-1/RATE_HZ) > .002):
            raise ValueError('Original frame/time order or rate invalid')
        if row.get('native_road_id') != geometry['road_id']:
            raise ValueError('Wrong original road identity')
        if row.get('native_lane_id') not in (geometry['driving_lane_id'], geometry['bicycle_lane_id']):
            raise ValueError('Wrong original lane identity')
        forward = row.get('native_forward_xy')
        if not isinstance(forward, list) or len(forward) != 2 or not all(
                type(v) in (int, float) and math.isfinite(v) for v in forward) or abs(
                    math.hypot(*forward)-1) > .01:
            raise ValueError('Invalid original heading')
        frames.append(frame)
        times.append(time)
        stopped.append(speed <= .1)
        areas.append(overlap_area(row.get('native_body_xy_m'), facility))
    intervals = []
    start = None
    for i, flag in enumerate(stopped + [False]):
        if flag and start is None:
            start = i
        if not flag and start is not None:
            if i-start >= MIN_STOP_FRAMES:
                intervals.append((start, i))
            start = None
    if not intervals:
        raise ValueError('No observed stationary interval')
    a, b = max(intervals, key=lambda pair: pair[1]-pair[0])
    max_area = max(areas[a:b])
    return {'format': 'c10052-facility-occupancy-observation-v1',
            'source_sha256': {path.name: sha(path) for path in paths},
            'original_frames': len(rows), 'stop_first_frame': frames[a],
            'stop_last_frame': frames[b-1], 'stop_duration_s': round((b-a)/RATE_HZ, 5),
            'max_stopped_overlap_m2': round(max_area, 6),
            'mean_stopped_overlap_m2': round(sum(areas[a:b])/(b-a), 6),
            'requested_exceptions': context['exceptions'],
            'observed_exception_status': 'unresolved',
            'native_facility_design_verified': geometry.get('native_facility_design_verified') is True,
            'yield_duty_measured': False, 'legal_verdict_claimed': False,
            'alley_entrance_bounds_m': alley}

"""C10052 rider-yield route and candidate control geometry for CPU preflight."""
import math
from alley_geometry import route
from geometry import body
from measure_facility import overlap_area

CONFLICT_BOUNDS_M=(-2.5,-5.0,2.5,-3.0)
RIDER_Y_M=-4.0
HOLD_ROUTE_INDEX=360
ROUTE_STEP_PER_FRAME=4
RELEASE_FRAME={'clear':249,'conflict':174}


def rider_body(x):
    return [[x-1.0,RIDER_Y_M-.35],[x-1.0,RIDER_Y_M+.35],
            [x+1.0,RIDER_Y_M+.35],[x+1.0,RIDER_Y_M-.35]]


def ego_route_index(frame,response,start_x=-45.0,release_shift_frames=0):
    if response not in RELEASE_FRAME or type(frame) is not int or frame<0:
        raise ValueError('Unknown rider response/frame')
    if start_x not in (-45.0,-55.0) or type(release_shift_frames) is not int or not 0<=release_shift_frames<=5:
        raise ValueError('Unknown rider candidate controls')
    path=route(start_x)
    hold=round((-9.0-start_x)/.1)
    approach=min(hold,frame*ROUTE_STEP_PER_FRAME)
    progress=max(0,frame-RELEASE_FRAME[response]-release_shift_frames)*ROUTE_STEP_PER_FRAME
    return min(len(path)-2,approach+progress)


def ego_pose(frame,response,start_x=-45.0,release_shift_frames=0):
    path=route(start_x)
    index=ego_route_index(frame,response,start_x,release_shift_frames)
    x,y=path[index]
    nx,ny=path[index+1]
    distance=math.hypot(nx-x,ny-y)
    heading=((nx-x)/distance,(ny-y)/distance)
    return {'center_xy':[x,y],'body_xy':body(x,y,heading),
            'forward_xy':list(heading),'route_index':index,
            'road_id':2 if y < -5 else 1,
            'speed_mps':8.0 if (frame<round((-9.0-start_x)/.4) or
                                 frame>RELEASE_FRAME[response]+release_shift_frames) and
                                 index<len(path)-2 else 0.0}


def rider_pose(frame):
    if type(frame) is not int or frame<0:
        raise ValueError('Invalid rider frame')
    x=-20+.2*max(0,min(frame-100,200))
    return {'center_xy':[x,RIDER_Y_M],'body_xy':rider_body(x),
            'speed_mps':4.0 if 100<frame<=300 else 0.0,
            'road_id':1,'lane_id':-2}


def check():
    path=route()
    assert path[0]==(-45.0,-1.5) and path[-1]==(0.0,-12.0)
    assert path[HOLD_ROUTE_INDEX]==(-9.0,-1.5)
    result={}
    for response in RELEASE_FRAME:
        occupied=[i for i in range(480)
                  if overlap_area(ego_pose(i,response)['body_xy'],CONFLICT_BOUNDS_M)>.01]
        result[response]={'first_conflict_index':occupied[0],
                          'last_conflict_index':occupied[-1],
                          'held_at_route_index':ego_route_index(120,response)}
        assert occupied[0]==(262 if response=='clear' else 187)
        assert ego_route_index(120,response)==HOLD_ROUTE_INDEX
        assert ego_pose(479,response)['road_id']==2
        assert ego_route_index(120,response,-55.0)==460
        assert ego_pose(0,response,-55.0)['center_xy']==[-55.0,-1.5]
        assert ego_pose(479,response,-55.0)['road_id']==2
        assert ego_route_index(480,response,-45.0,5)>500
    rider=[i for i in range(480) if overlap_area(rider_pose(i)['body_xy'],CONFLICT_BOUNDS_M)>.01]
    assert rider[0]==183 and rider[-1]==217
    return {'route_points':len(path),'rider_conflict_indices':[rider[0],rider[-1]],
            'ego':result,'native_readback_verified':False,'physical_success_claimed':False}


if __name__=='__main__':
    import json
    print(json.dumps(check(),indent=2))

"""Four distinct rider-yield Native construction policies and measured triggers."""
import hashlib
import json
from pathlib import Path
from measure_facility import overlap_area
from rider_engineering import CONFLICT_BOUNDS_M, RELEASE_FRAME, ego_pose

NAMES=('primary','fallback1','fallback2','fallback3')
RIDER_TYPES=('bicycle','electric_bicycle','electric_scooter')


def parameters(rider_type,response,candidate):
    if rider_type not in RIDER_TYPES or response not in RELEASE_FRAME or candidate not in NAMES:
        raise ValueError('Unknown exact rider case or candidate')
    return {'rider_type':rider_type,'response':response,'candidate':candidate,
            'approach_start_x_m':-55.0 if candidate=='fallback1' else -45.0,
            'release_shift_frames':5 if candidate=='fallback2' else 0,
            'reference_camera_xyz_m':[8.0,-10.0,14.0] if candidate=='fallback3' else [10.0,-8.0,10.0],
            'ego_speed_mps':8.0,'rider_speed_mps':4.0,
            'rider_y_m':-4.0,'conflict_bounds_m':[-2.5,-5.0,2.5,-3.0]}


def trigger_values(approach_start_x_m,first_ego_frame,expected_ego_frame,
                   visible_conflict_frames,total_conflict_frames):
    if type(approach_start_x_m) not in (int,float) or not -60<=approach_start_x_m<=-35:
        raise ValueError('Invalid measured start')
    if type(first_ego_frame) is not int or type(expected_ego_frame) is not int:
        raise ValueError('Invalid measured conflict entry frame')
    if type(visible_conflict_frames) is not int or type(total_conflict_frames) is not int or not 0<=visible_conflict_frames<=total_conflict_frames or total_conflict_frames==0:
        raise ValueError('Invalid measured visibility count')
    runway_m=-9.0-approach_start_x_m
    error_frames=abs(first_ego_frame-expected_ego_frame)
    visibility=visible_conflict_frames/total_conflict_frames
    return {'approach_runway_m':runway_m,'ego_entry_error_frames':error_frames,
            'body_visible_fraction':round(visibility,6),
            'fallback1_trigger_measured':runway_m<35.0,
            'fallback2_trigger_measured':error_frames>5,
            'fallback3_trigger_measured':visibility<.95}


def evaluate_sources(folder):
    folder=Path(folder)
    manifest=json.loads((folder/'rider-trigger-sources.json').read_text())
    if manifest.get('source_kind')!='synthetic_cpu_fixture' or manifest.get('accepted') is not False:
        raise ValueError('Invalid trigger source scope')
    for name,digest in manifest['sha256'].items():
        path=folder/name
        if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest()!=digest:
            raise ValueError('Rider trigger source hash differs: '+name)
    samples=[json.loads(line) for line in (folder/'native_rider_ego_samples.jsonl').read_text().splitlines()]
    visibility=[json.loads(line) for line in (folder/'camera_visibility.jsonl').read_text().splitlines()]
    if len(samples)!=480 or len(visibility)!=480:
        raise ValueError('Missing trigger frames')
    if any((a['native_frame'],a['time_s'])!=(b['native_frame'],b['time_s'])
           for a,b in zip(samples,visibility)):
        raise ValueError('Trigger frame/time join failed')
    ego=[i for i,row in enumerate(samples)
         if overlap_area(row['ego_body_xy'],CONFLICT_BOUNDS_M)>.01]
    rider=[i for i,row in enumerate(samples)
           if overlap_area(row['rider_body_xy'],CONFLICT_BOUNDS_M)>.01]
    if not ego or not rider:
        raise ValueError('Missing source-bound conflict observation')
    start_x=sum(p[0] for p in samples[0]['ego_body_xy'])/4
    visible=sum(visibility[i]['rider_and_ego_body_visible'] is True for i in rider)
    values=trigger_values(start_x,samples[ego[0]]['native_frame'],
                          manifest['expected_ego_frame'],visible,len(rider))
    return {'case_id':manifest['case_id'],'fixture':manifest['fixture'],
            'first_ego_frame':samples[ego[0]]['native_frame'],
            'last_rider_frame':samples[rider[-1]]['native_frame'],
            'rider_conflict_frames':len(rider), 'visible_conflict_frames':visible,
            **values}


def check():
    base=parameters('bicycle','clear','primary')
    changed=[]
    for candidate in NAMES[1:]:
        variant=parameters('bicycle','clear',candidate)
        different={key for key in ('approach_start_x_m','release_shift_frames','reference_camera_xyz_m')
                   if variant[key]!=base[key]}
        changed.append(different)
    assert changed==[{'approach_start_x_m'},{'release_shift_frames'},
                     {'reference_camera_xyz_m'}]
    assert ego_pose(0,'clear',-55.0)['center_xy']==[-55.0,-1.5]
    assert ego_pose(479,'clear',-55.0)['road_id']==2
    assert ego_pose(479,'clear',-45.0,5)['road_id']==2
    return {'cases':6,'candidates_per_case':4,'distinct_knob_sets':[sorted(x) for x in changed],
            'original_native_actor_verified':False,'camera_visibility_verified':False}


if __name__=='__main__':
    import json
    print(json.dumps(check(),indent=2))

"""Source-bound synthetic rider/ego conflict timing, without a legal yield verdict."""
import hashlib
import json
import math
from pathlib import Path
from measure_facility import overlap_area, rectangle

RATE_HZ = 20
RIDERS = ('bicycle', 'electric_bicycle', 'electric_scooter')


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def _rows(path):
    rows = [json.loads(line) for line in Path(path).read_text().splitlines() if line.strip()]
    if len(rows) != 480:
        raise ValueError('Expected 480 original frames')
    for index, row in enumerate(rows):
        if type(row.get('native_frame')) is not int or row['native_frame'] < 0:
            raise ValueError('Invalid original frame')
        if type(row.get('time_s')) not in (float, int) or not math.isfinite(row['time_s']):
            raise ValueError('Invalid original time')
        if index:
            prior = rows[index - 1]
            if row['native_frame'] != prior['native_frame'] + 1 or abs(row['time_s'] - prior['time_s'] - .05) > .002:
                raise ValueError('Original frame/time join failed')
        for actor in ('ego', 'rider'):
            speed = row.get(actor + '_speed_mps')
            if type(speed) not in (float, int) or not math.isfinite(speed) or speed < 0:
                raise ValueError('Invalid original speed')
            if row.get(actor + '_body_xy') is None:
                raise ValueError('Missing original body')
    return rows


def measure(samples_path, geometry_path, manifest_path):
    samples_path, geometry_path, manifest_path = map(Path, (samples_path, geometry_path, manifest_path))
    for path in (samples_path, geometry_path, manifest_path):
        if not path.is_file():
            raise ValueError('Missing original source ' + path.name)
    manifest = json.loads(manifest_path.read_text())
    if manifest.get('source_kind') != 'synthetic_native_shaped_diagnostic' or manifest.get('accepted') is not False:
        raise ValueError('Invalid source scope')
    if manifest.get('samples_sha256') != sha(samples_path) or manifest.get('geometry_sha256') != sha(geometry_path):
        raise ValueError('Changed original source bytes')
    geometry = json.loads(geometry_path.read_text())
    conflict = rectangle(geometry.get('conflict_native_xy_bounds_m'), 'conflict bounds')
    facility = rectangle(geometry.get('bicycle_facility_native_xy_bounds_m'), 'facility bounds')
    if not (facility[0] <= conflict[0] < conflict[2] <= facility[2] and
            facility[1] <= conflict[1] < conflict[3] <= facility[3]):
        raise ValueError('Conflict is outside facility')
    rider_type = manifest.get('rider_type')
    if rider_type not in RIDERS:
        raise ValueError('Unqualified rider type')
    if geometry.get('ego_road_ids') != [1, 2]:
        raise ValueError('Missing authored ego road transition')
    rows = _rows(samples_path)
    if any(row.get('rider_type') != rider_type or row.get('rider_actor_id') != manifest.get('rider_actor_id')
           or row.get('rider_native_road_id') != geometry.get('rider_road_id')
           or row.get('rider_native_lane_id') != geometry.get('rider_lane_id')
           or row.get('ego_native_road_id') not in geometry['ego_road_ids'] for row in rows):
        raise ValueError('Original actor or Native road/lane join failed')
    roads = [row['ego_native_road_id'] for row in rows]
    if roads != sorted(roads) or set(roads) != {1, 2}:
        raise ValueError('Original ego road transition missing or reversed')
    rider = [i for i, row in enumerate(rows) if overlap_area(row['rider_body_xy'], conflict) > .01]
    ego = [i for i, row in enumerate(rows) if overlap_area(row['ego_body_xy'], conflict) > .01]
    if not rider or not ego:
        raise ValueError('Missing observed conflict occupancy')
    if rider[0] >= ego[0]:
        raise ValueError('Rider did not arrive before ego')
    first_ego, last_rider = ego[0], rider[-1]
    simultaneous = len(set(rider) & set(ego))
    return {'format': 'c10052-rider-conflict-timing-v1',
            'rider_type': rider_type, 'rider_actor_id': manifest['rider_actor_id'],
            'first_rider_frame': rows[rider[0]]['native_frame'],
            'last_rider_frame': rows[last_rider]['native_frame'],
            'first_ego_frame': rows[first_ego]['native_frame'],
            'simultaneous_conflict_frames': simultaneous,
            'clearance_s': round((first_ego-last_rider)*.05, 6),
            'ego_entered_after_rider_cleared': first_ego > last_rider,
            'source_sha256': {'samples': sha(samples_path), 'geometry': sha(geometry_path),
                              'manifest': sha(manifest_path)},
            'source_scope': 'synthetic diagnostic; facility designation and legal priority unverified',
            'accepted': False}
